-- Baza „dcn-odkrywcy” (Cloudflare D1): potwierdzanie nowych produktów. Utworzona 20.10.2026.
CREATE TABLE IF NOT EXISTS subs (code TEXT PRIMARY KEY, device TEXT NOT NULL, nick TEXT, name TEXT, at INTEGER, status TEXT NOT NULL DEFAULT 'pending', yes INTEGER NOT NULL DEFAULT 0, no INTEGER NOT NULL DEFAULT 0, views INTEGER NOT NULL DEFAULT 0, checks TEXT, iph TEXT, wanted INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS subs_device ON subs(device);
CREATE TABLE IF NOT EXISTS votes (code TEXT NOT NULL, device TEXT NOT NULL, vote TEXT NOT NULL, at INTEGER, iph TEXT, counted INTEGER NOT NULL DEFAULT 1, PRIMARY KEY (code, device));
CREATE TABLE IF NOT EXISTS views (code TEXT NOT NULL, device TEXT NOT NULL, PRIMARY KEY (code, device));
CREATE TABLE IF NOT EXISTS devices (device TEXT PRIMARY KEY, confirmed INTEGER NOT NULL DEFAULT 0, rejected INTEGER NOT NULL DEFAULT 0, disagree INTEGER NOT NULL DEFAULT 0, streak INTEGER NOT NULL DEFAULT 0);
-- 20.10.2026: dodano kolumnę streak (potwierdzone od ostatniego odrzucenia): ALTER TABLE devices ADD COLUMN streak INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS misses (code TEXT PRIMARY KEY, n INTEGER NOT NULL DEFAULT 0, last INTEGER);
CREATE TABLE IF NOT EXISTS miss_dev (code TEXT NOT NULL, device TEXT NOT NULL, PRIMARY KEY (code, device));
CREATE TABLE IF NOT EXISTS daily (device TEXT NOT NULL, day TEXT NOT NULL, kind TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (device, day, kind));
